select public.prepify_load_bank('Chemistry', 13, $j$[["Organic chemistry is the study of compounds of:",["nitrogen","carbon","oxygen","sulphur"],"B",1,0,"d77b221f8e95"],["The ability of carbon atoms to join with each other to form long chains and rings is called:",["isomerism","catenation","polymerization","hydrolysis"],"B",3,0,"46ee475fd03a"],["Carbon forms four covalent bonds because it is:",["monovalent","divalent","trivalent","tetravalent"],"D",1,0,"e787bd64400d"],["Which of these is NOT usually classed as an organic compound?",["Methane","Ethanol","Carbon dioxide","Glucose"],"C",3,0,"540bd5c456b2"],["The main natural sources of organic compounds are:",["coal, petroleum, natural gas and living things","sand and rocks","sea salt and air","metals and ores"],"A",1,0,"342b7e89c22e"],["The functional group of an alcohol is:",["–OH","–COOH","–CHO","–NH₂"],"A",3,0,"5719467b486c"],["The functional group –COOH belongs to:",["alcohols","aldehydes","carboxylic acids","ketones"],"C",3,0,"226c43827bdc"],["The functional group –CHO belongs to:",["ketones","aldehydes","esters","amines"],"B",3,0,"eb127fdd8f37"],["A homologous series is a family of compounds in which each member differs from the next by:",["–CH₂–","–OH","–H₂O","–CO₂"],"A",3,0,"b11a39c32ae6"],["Members of a homologous series have:",["the same general formula and similar chemical properties","different functional groups","identical boiling points","no carbon"],"A",3,0,"662b46219a5a"],["Compounds with the same molecular formula but different structures are called:",["isotopes","isomers","allotropes","polymers"],"B",3,0,"d423c8a36dd1"],["Butane (C₄H₁₀) and isobutane (C₄H₁₀) are examples of:",["isotopes","isomers","allotropes","homologues with different formulas"],"B",5,0,"729adfe8a3b3"],["The prefix \"prop-\" in an organic name shows a chain of:",["1 carbon","2 carbons","3 carbons","4 carbons"],"C",1,0,"1cba8e974b02"],["The prefix \"eth-\" shows a chain of:",["1 carbon","2 carbons","3 carbons","5 carbons"],"B",1,0,"51595e221a70"],["Heating coal strongly in the absence of air is called:",["fractional distillation","destructive distillation","combustion","cracking"],"B",3,0,"18796891034b"],["Destructive distillation of coal produces coke, coal gas and:",["coal tar","crude oil","natural gas only","sand"],"A",3,0,"d500e89a2130"],["Crude petroleum is separated into useful parts such as petrol and diesel by:",["filtration","fractional distillation","crystallization","chromatography"],"B",3,0,"35addaefa5d5"],["A chemist finds that a liquid turns blue litmus red and contains the –COOH group. The compound is most likely:",["an alcohol","a carboxylic acid","an alkane","an ester"],"B",3,1,"7eb5cf6cc927"],["A formula that shows every atom and bond in a molecule is a:",["molecular formula","structural formula","empirical formula","condensed name"],"B",3,0,"43d794fae102"],["Vinegar contains which organic compound?",["Ethanol","Ethanoic (acetic) acid","Methane","Glucose"],"B",1,0,"6b310fdf1e59"],["Ethanol belongs to which class of compounds?",["Alcohols","Alkanes","Carboxylic acids","Ketones"],"A",1,0,"802b82936475"],["Esters are known for their:",["pleasant fruity smells","sour taste","ability to conduct electricity","magnetic properties"],"A",3,0,"a1407758c2d9"],["A student finds a compound that contains only carbon and hydrogen. It is a:",["carbohydrate","hydrocarbon","carboxylic acid","protein"],"B",1,1,"e7d942303b6e"],["Why are there millions of organic compounds but far fewer inorganic ones?",["Carbon forms stable chains, rings and multiple bonds","Carbon is the most abundant element","Carbon is a metal","Organic compounds are all gases"],"A",5,0,"ec0cbab8238e"],["Most organic compounds are:",["ionic and high-melting","covalent and have relatively low melting points","metals","insoluble in all solvents"],"B",3,0,"38865968a2c2"],["Which of these products is made from organic compounds?",["Plastics and medicines","Glass","Table salt","Iron nails"],"A",1,0,"4be0efad8533"],["The functional group in amines is:",["–NH₂","–OH","–COOH","–CHO"],"A",3,0,"ada8aa4a46f3"],["A molecule has the condensed formula CH₃CH₂OH. How many carbon atoms does it contain?",["1","2","3","6"],"B",3,1,"c1acebdae081"],["The general formula of the alcohol series (alkanols) is:",["CₙH₂ₙ₊₁OH","CₙH₂ₙ","CₙH₂ₙ₋₂","CₙH₂ₙ₊₁COOH"],"A",5,0,"9f86c25547e1"],["In a homologous series, as the chain gets longer, the boiling point generally:",["decreases","increases","stays the same","becomes zero"],"B",5,0,"43796beba318"],["Which group is present in every alcohol, such as methanol and ethanol?",["–OH","–COOH","–CHO","–NH₂"],"A",3,0,"5719467b486c"],["Ethanoic acid (CH₃COOH) belongs to the class of:",["alcohols","aldehydes","carboxylic acids","ketones"],"C",3,0,"226c43827bdc"],["Glucose and fructose both have the formula C₆H₁₂O₆ but different structures. They are:",["isotopes","isomers","allotropes","polymers"],"B",5,0,"d423c8a36dd1"],["The prefix \"but-\" in butane shows a chain of:",["2 carbons","3 carbons","4 carbons","5 carbons"],"C",1,0,"1cba8e974b02"],["Petrol, diesel and kerosene are obtained from crude oil by:",["filtration","fractional distillation","crystallization","chromatography"],"B",3,0,"35addaefa5d5"],["Coke, coal gas and coal tar are produced when coal is:",["burnt in plenty of air","heated strongly without air","dissolved in water","cracked with a catalyst"],"B",3,0,"18796891034b"],["Carbon atoms can link together to form very long chains. This property is called:",["isomerism","catenation","hydrolysis","oxidation"],"B",1,0,"46ee475fd03a"],["Which of these is an inorganic compound?",["Ethanol","Methane","Sodium chloride","Glucose"],"C",3,0,"540bd5c456b2"],["The pleasant smells of many fruits and perfumes come from compounds called:",["esters","alkanes","amines","acids"],"A",3,0,"a1407758c2d9"],["How many carbon atoms are in one molecule of octane?",["9","8","10","7"],"B",1,0,"gen-chemistry-c13-carbon-count"],["How many carbon atoms are in one molecule of propane?",["2","3","5","4"],"B",1,0,"gen-chemistry-c13-carbon-count"],["How many carbon atoms are in one molecule of propanol?",["2","3","5","4"],"B",1,0,"gen-chemistry-c13-carbon-count"],["How many carbon atoms are in one molecule of ethanol?",["1","2","3","4"],"B",1,0,"gen-chemistry-c13-carbon-count"],["How many carbon atoms are in one molecule of butanol?",["5","3","4","6"],"C",1,0,"gen-chemistry-c13-carbon-count"],["How many carbon atoms are in one molecule of methanol?",["4","1","2","3"],"B",1,0,"gen-chemistry-c13-carbon-count"]]$j$::jsonb, true);
select public.prepify_load_bank('Chemistry', 14, $j$[["Hydrocarbons are compounds made of:",["carbon and oxygen","carbon and hydrogen","hydrogen and oxygen","carbon, hydrogen and nitrogen"],"B",1,0,"d6dc9122f7e7"],["The general formula of alkanes is:",["CₙH₂ₙ₊₂","CₙH₂ₙ","CₙH₂ₙ₋₂","CₙHₙ"],"A",1,0,"608994cbfd39"],["The general formula of alkenes is:",["CₙH₂ₙ₊₂","CₙH₂ₙ","CₙH₂ₙ₋₂","CₙH₂ₙ₊₁"],"B",1,0,"133e8b7a8c6b"],["The general formula of alkynes is:",["CₙH₂ₙ₊₂","CₙH₂ₙ","CₙH₂ₙ₋₂","CₙH₂ₙ₊₄"],"C",3,0,"a8226fbd4fc2"],["Alkanes are called saturated hydrocarbons because they contain:",["only single bonds between carbon atoms","at least one double bond","a triple bond","no hydrogen"],"A",3,0,"fef0018be32e"],["The simplest alkane is:",["ethane","methane","ethene","ethyne"],"B",1,0,"c85038edc49a"],["The molecular formula of an alkane with 5 carbon atoms is:",["C₅H₁₀","C₅H₁₂","C₅H₈","C₅H₁₄"],"B",5,0,"e50bce0a5269"],["The molecular formula of an alkene with 3 carbon atoms is:",["C₃H₈","C₃H₆","C₃H₄","C₃H₃"],"B",5,0,"7aaf91744c24"],["The molecular formula of an alkyne with 4 carbon atoms is:",["C₄H₁₀","C₄H₈","C₄H₆","C₄H₄"],"C",5,0,"f4d475e4a8c3"],["Ethene (C₂H₄) contains a:",["single bond only","carbon–carbon double bond","carbon–carbon triple bond","benzene ring"],"B",3,0,"95a466a22bfb"],["Ethyne (C₂H₂) is commonly called:",["methane","acetylene","propane","butane"],"B",3,0,"b6a961e54593"],["The gas used with oxygen in welding torches is:",["methane","ethyne (acetylene)","propane","ethane"],"B",3,1,"7e636a27683f"],["When bromine water is shaken with an alkene, it:",["turns from orange-brown to colourless","turns blue","turns red","stays orange-brown"],"A",3,0,"1ba3013fe8b5"],["A student shakes two gases with bromine water. Gas X decolourizes it; gas Y does not. Which statement is correct?",["X is unsaturated and Y is saturated","X is saturated and Y is unsaturated","Both are alkanes","Both are alkenes"],"A",5,1,"370ea673df01"],["Alkanes react with chlorine in sunlight by:",["addition","substitution","polymerization","neutralization"],"B",3,0,"2e132f4ecc12"],["Alkenes typically undergo:",["addition reactions","substitution reactions only","no reactions","neutralization"],"A",3,0,"e4a94939eb8e"],["Adding hydrogen to an alkene in the presence of a nickel catalyst is called:",["hydration","hydrogenation","halogenation","cracking"],"B",3,0,"f950f1f6f39c"],["Vegetable ghee (margarine) is made from vegetable oils by:",["hydrogenation","dehydration","combustion","fermentation"],"A",3,1,"597a617139c2"],["Complete combustion of methane produces:",["carbon monoxide and water","carbon dioxide and water","carbon and hydrogen","methanol"],"B",1,0,"28476fa147cb"],["The balanced equation for complete combustion of methane is:",["CH₄ + O₂ → CO₂ + H₂O","CH₄ + 2O₂ → CO₂ + 2H₂O","2CH₄ + O₂ → 2CO + 4H₂","CH₄ + 3O₂ → CO₂ + 3H₂O"],"B",5,0,"56e798544d2b"],["A gas heater in a closed room burns fuel with too little oxygen and produces a poisonous gas. The gas is:",["carbon dioxide","carbon monoxide","nitrogen","water vapour"],"B",3,1,"430259d1706f"],["The main component of natural gas is:",["ethane","methane","propane","butane"],"B",1,0,"2c66c407247e"],["LPG (liquefied petroleum gas) used in cylinders is mainly:",["methane and ethane","propane and butane","ethene and ethyne","hydrogen"],"B",3,0,"1c1099c50c5a"],["Breaking large hydrocarbon molecules into smaller, more useful ones is called:",["cracking","polymerization","distillation","condensation"],"A",3,0,"ed34155105fc"],["Polythene is made by joining many ethene molecules together. This process is:",["cracking","polymerization","hydrogenation","combustion"],"B",3,0,"2f4f05e4336b"],["The molar mass of propane (C₃H₈) is (C = 12, H = 1):",["36 g mol⁻¹","44 g mol⁻¹","42 g mol⁻¹","48 g mol⁻¹"],"B",5,0,"9ce64a9326e8"],["Which is the next member after propane in the alkane series?",["Butane","Ethane","Pentane","Propene"],"A",1,0,"855c9506f83a"],["Methane is formed naturally in marshes and by animal digestion. It is also called:",["marsh gas","laughing gas","water gas","noble gas"],"A",3,0,"6929c1891ec5"],["Alkynes are more reactive than alkanes because they contain:",["only single bonds","a triple bond","no carbon","ionic bonds"],"B",3,0,"3262f606a57f"],["A student burns a hydrocarbon and gets a sooty yellow flame. This suggests:",["incomplete combustion","complete combustion","no combustion","the fuel is water"],"A",3,1,"f55552956b7a"],["The general formula CₙH₂ₙ₋₂ belongs to the:",["alkanes","alkenes","alkynes","alcohols"],"C",3,0,"a8226fbd4fc2"],["Alkenes are called unsaturated hydrocarbons because they contain:",["only single bonds","at least one carbon–carbon double bond","no hydrogen","oxygen atoms"],"B",3,0,"fef0018be32e"],["Bromine water is shaken with hexane (an alkane). The orange-brown colour:",["disappears quickly","remains","turns blue","turns green"],"B",5,0,"1ba3013fe8b5"],["Methane reacts with chlorine in sunlight and a hydrogen atom is replaced by chlorine. This is:",["addition","substitution","polymerization","cracking"],"B",3,0,"2e132f4ecc12"],["Margarine is made by passing hydrogen through vegetable oil with a nickel catalyst. This reaction is:",["hydrogenation","dehydration","fermentation","combustion"],"A",3,1,"597a617139c2"],["Burning a fuel in too little oxygen can produce the poisonous gas:",["carbon monoxide","oxygen","nitrogen","helium"],"A",3,1,"430259d1706f"],["Plastic shopping bags made of polythene are formed by:",["cracking","polymerization of ethene","hydrogenation","fermentation"],"B",3,0,"2f4f05e4336b"],["The gas supplied to homes through pipes in Pakistan (Sui gas) is mainly:",["methane","propane","butane","ethyne"],"A",1,1,"2c66c407247e"],["The alkane that comes just before butane in the series is:",["Methane","Ethane","Propane","Pentane"],"C",1,0,"855c9506f83a"],["The molecular formula of hexane is:",["C₆H₁₂","C₆H₁₆","C₆H₁₀","C₆H₁₄"],"D",3,0,"gen-chemistry-c14-formula"],["The molecular formula of butyne is:",["C₄H₁₂","C₄H₁₀","C₄H₆","C₄H₈"],"C",3,0,"gen-chemistry-c14-formula"],["The molecular formula of pentane is:",["C₅H₈","C₅H₁₂","C₅H₁₄","C₅H₁₀"],"B",3,0,"gen-chemistry-c14-formula"],["The molecular formula of propane is:",["C₃H₈","C₃H₄","C₃H₁₀","C₃H₆"],"A",3,0,"gen-chemistry-c14-formula"],["The molecular formula of hexene is:",["C₆H₁₂","C₆H₁₄","C₆H₁₆","C₆H₁₀"],"A",3,0,"gen-chemistry-c14-formula"],["The molecular formula of pentyne is:",["C₅H₁₂","C₅H₁₀","C₅H₁₄","C₅H₈"],"D",3,0,"gen-chemistry-c14-formula"],["The molar mass of propene (C₃H₆) is (C = 12, H = 1):",["42 g mol⁻¹","40 g mol⁻¹","56 g mol⁻¹","36 g mol⁻¹"],"A",3,0,"9ce64a9326e8"],["The molar mass of hexene (C₆H₁₂) is (C = 12, H = 1):",["98 g mol⁻¹","84 g mol⁻¹","72 g mol⁻¹","82 g mol⁻¹"],"B",3,0,"9ce64a9326e8"],["The molar mass of hexane (C₆H₁₄) is (C = 12, H = 1):",["72 g mol⁻¹","86 g mol⁻¹","84 g mol⁻¹","100 g mol⁻¹"],"B",3,0,"9ce64a9326e8"],["The molar mass of pentene (C₅H₁₀) is (C = 12, H = 1):",["60 g mol⁻¹","70 g mol⁻¹","68 g mol⁻¹","84 g mol⁻¹"],"B",3,0,"9ce64a9326e8"],["The molar mass of octene (C₈H₁₆) is (C = 12, H = 1):",["126 g mol⁻¹","96 g mol⁻¹","110 g mol⁻¹","112 g mol⁻¹"],"D",3,0,"9ce64a9326e8"],["The molar mass of methane (CH₄) is (C = 12, H = 1):",["14 g mol⁻¹","12 g mol⁻¹","30 g mol⁻¹","16 g mol⁻¹"],"D",3,0,"9ce64a9326e8"],["Complete combustion of one molecule of ethane (C₂H₆) produces:",["2 CO₂ and 3 H₂O","4 CO₂ and 3 H₂O","2 CO₂ and 6 H₂O","3 CO₂ and 2 H₂O"],"A",5,0,"gen-chemistry-c14-combustion-products"],["Complete combustion of one molecule of butane (C₄H₁₀) produces:",["5 CO₂ and 4 H₂O","8 CO₂ and 5 H₂O","4 CO₂ and 5 H₂O","4 CO₂ and 10 H₂O"],"C",5,0,"gen-chemistry-c14-combustion-products"],["Complete combustion of one molecule of butene (C₄H₈) produces:",["4 CO₂ and 4 H₂O","8 CO₂ and 4 H₂O","5 CO₂ and 5 H₂O","4 CO₂ and 8 H₂O"],"A",5,0,"gen-chemistry-c14-combustion-products"],["Complete combustion of one molecule of methane (CH₄) produces:",["1 CO₂ and 4 H₂O","2 CO₂ and 2 H₂O","2 CO₂ and 1 H₂O","1 CO₂ and 2 H₂O"],"D",5,0,"gen-chemistry-c14-combustion-products"],["Complete combustion of one molecule of hexane (C₆H₁₄) produces:",["6 CO₂ and 7 H₂O","7 CO₂ and 6 H₂O","6 CO₂ and 14 H₂O","12 CO₂ and 7 H₂O"],"A",5,0,"gen-chemistry-c14-combustion-products"],["Complete combustion of one molecule of hexene (C₆H₁₂) produces:",["6 CO₂ and 12 H₂O","6 CO₂ and 6 H₂O","12 CO₂ and 6 H₂O","7 CO₂ and 7 H₂O"],"B",5,0,"gen-chemistry-c14-combustion-products"]]$j$::jsonb, true);
select public.prepify_load_bank('Chemistry', 15, $j$[["Biochemistry is the study of:",["chemical processes in living things","rocks and minerals","stars","metals only"],"A",1,0,"8e9496d8777d"],["The molecular formula of glucose is:",["C₆H₁₂O₆","C₁₂H₂₂O₁₁","CH₄","C₂H₅OH"],"A",1,0,"7446a668a98a"],["Glucose is an example of a:",["monosaccharide","disaccharide","polysaccharide","protein"],"A",3,0,"6ec0a643da44"],["Sucrose (table sugar) is a:",["monosaccharide","disaccharide","polysaccharide","lipid"],"B",3,0,"bc0c5d90c846"],["Starch and cellulose are:",["monosaccharides","disaccharides","polysaccharides","vitamins"],"C",3,0,"9812bb7eefce"],["Proteins are made of long chains of:",["glucose","amino acids","fatty acids","nucleotides"],"B",1,0,"7db0b34b1b1b"],["The bond that joins amino acids in a protein is the:",["peptide bond","ionic bond","hydrogen bond only","glycosidic bond"],"A",3,0,"6263078ec070"],["Fats and oils belong to the group of:",["carbohydrates","proteins","lipids","vitamins"],"C",1,0,"042e1fd7ffe3"],["Fats are formed from glycerol and:",["amino acids","fatty acids","glucose","nucleic acids"],"B",3,0,"6f464f69b7e8"],["Enzymes are biological catalysts that are mostly made of:",["carbohydrates","proteins","lipids","minerals"],"B",3,0,"5c37be37f60b"],["DNA and RNA are:",["carbohydrates","nucleic acids","lipids","vitamins"],"B",1,0,"9f650397d3dc"],["A student adds iodine solution to a food sample and it turns blue-black. The food contains:",["starch","protein","fat","vitamin C"],"A",3,1,"0423d67aded9"],["Benedict's solution turns brick-red when heated with:",["starch","a reducing sugar such as glucose","fat","protein"],"B",3,0,"0c90a03e6c0d"],["The biuret test gives a violet (purple) colour with:",["proteins","starch","fats","glucose"],"A",3,0,"6580adf62e98"],["A food sample leaves a translucent grease spot on paper. It contains:",["lipids","protein","starch","vitamin C"],"A",3,1,"dd77547a0e5d"],["Vitamin C deficiency causes:",["rickets","scurvy","night blindness","anaemia"],"B",3,0,"70a0062721ec"],["Vitamin D deficiency in children causes:",["scurvy","rickets","goitre","beriberi"],"B",3,0,"cfb5a29b47a6"],["Night blindness is caused by a lack of:",["Vitamin A","Vitamin B","Vitamin C","Vitamin D"],"A",3,0,"bbd73dc627f7"],["Which vitamins are fat-soluble?",["A, D, E and K","B and C","C only","B only"],"A",5,0,"f7f3dd97726b"],["Sunlight helps the skin produce:",["Vitamin A","Vitamin C","Vitamin D","Vitamin K"],"C",1,0,"0ac9cf87c7fb"],["A sailor on a long voyage without fresh fruit develops bleeding gums. The most likely cause is a lack of:",["vitamin C","vitamin D","protein","fat"],"A",5,1,"a357f3246da1"],["The main function of carbohydrates in the body is to:",["provide energy","build muscles","carry genetic information","fight infection only"],"A",1,0,"17a60bffe2c0"],["Proteins are needed mainly for:",["growth and repair of body tissues","quick energy only","making bones soft","storing genetic code"],"A",1,0,"ad4cffdc4fa6"],["Which food is a good source of protein?",["Eggs","Sugar","Butter","Rice"],"A",1,0,"d7a614aec803"],["Cellulose in our diet mainly provides:",["fibre (roughage) that helps digestion","quick energy","vitamins","protein"],"A",3,0,"8773c36fddb8"],["Glycogen is the form in which animals store:",["glucose","fat","protein","vitamins"],"A",5,0,"928e49555665"],["An enzyme stops working at very high temperatures because it:",["becomes denatured","turns into a vitamin","gains energy","dissolves in fat"],"A",5,0,"cb98634875d7"],["Plants make glucose by photosynthesis using carbon dioxide, water and:",["sunlight","oxygen only","nitrogen","fat"],"A",3,0,"3e97f95e8622"],["Which is a disaccharide found in milk?",["Lactose","Starch","Glucose","Cellulose"],"A",3,0,"ea2fac1bdf22"],["A person on a diet of only white rice for months is at risk of lacking:",["protein and vitamins","carbohydrates","energy","starch"],"A",3,1,"9b17a31f4dfb"],["Table sugar (sucrose) is made of two sugar units joined together. It is a:",["monosaccharide","disaccharide","polysaccharide","protein"],"B",3,0,"bc0c5d90c846"],["Rice, bread and potatoes are rich in starch, which is a:",["monosaccharide","disaccharide","polysaccharide","lipid"],"C",1,0,"9812bb7eefce"],["A food sample turns violet when biuret reagent is added. It contains:",["starch","protein","fat","glucose"],"B",3,1,"6580adf62e98"],["A sample of fruit juice turns Benedict's solution brick-red on heating. It contains:",["a reducing sugar such as glucose","starch only","protein","fat"],"A",3,1,"0c90a03e6c0d"],["Children who get little sunlight and no milk may develop soft, bent bones. This disease is:",["scurvy","rickets","goitre","night blindness"],"B",3,1,"cfb5a29b47a6"],["Bleeding gums caused by a lack of fresh fruit and vegetables is the disease:",["scurvy","rickets","anaemia","beriberi"],"A",3,0,"70a0062721ec"],["Amino acids join together to form:",["carbohydrates","proteins","fats","vitamins"],"B",1,0,"7db0b34b1b1b"],["Athletes eat pasta before a race because carbohydrates mainly:",["provide energy","repair bones","carry genes","fight infection"],"A",1,1,"17a60bffe2c0"],["Milk sugar is called:",["sucrose","lactose","starch","cellulose"],"B",3,0,"ea2fac1bdf22"],["Heating an enzyme to 90 °C destroys its shape so it stops working. The enzyme has been:",["denatured","activated","multiplied","frozen"],"A",5,0,"cb98634875d7"]]$j$::jsonb, true);
select public.prepify_load_bank('Computer Science', 1, $j$[["The \"Pascaline\" (1642) performed basic arithmetic using which specific mechanism?",["Vacuum tubes","Punched cards","Gears and wheels","Transistors"],"C",1,0,"7ca8e8ca9e51"],["Which component is described as the \"backbone\" of the computer that enables communication between all hardware parts?",["The Central Processing Unit","The Motherboard","The Hard Disk Drive","The Power Supply Unit"],"B",1,0,"6f498f37c8be"],["Which generation introduced the standard use of keyboards and monitors?",["Second Generation","Third Generation","Fourth Generation","Fifth Generation"],"B",1,0,"4710b27c8d10"],["\"Self-regulation and stability\" are the defining characteristics of which system type?",["Natural Systems","Artificial Systems","Operating Systems","Network Systems"],"A",1,0,"40cd9ff9194c"],["Which input device is specifically used to convert \"sound into digital signals\"?",["Scanner","Microphone","Barcode Reader","Digital Camera"],"B",1,0,"2112edea75a6"],["In the microprocessor, if the system needs to compare two numbers to see which is larger, which unit handles this task?",["Control Unit (CU)","Arithmetic Logic Unit (ALU)","L3 Cache","Memory Address Register"],"B",1,0,"5801bc811ef9"],["In Von Neumann Architecture, where are \"instructions and program data\" stored according to the core concept?",["In separate physical devices","Together in the same memory","Only in the Accumulator register","Directly on the Control Bus"],"B",1,0,"9572ac25cbc0"],["What is the specific role of the \"Program Counter (PC)\" register during the instruction cycle?",["It holds the result of a mathematical addition","It contains the memory address of the next instruction to be executed","It decodes the current instruction into binary code","It manages the flow of data to the printer"],"B",1,0,"8819ee05fd3c"],["If a CPU needs to move data but NOT the memory address, which pathway is utilized?",["Address Bus","Data Bus","Control Bus","Expansion Slot"],"B",1,1,"f6c86dd9b5fd"],["Within the microprocessor, which unit manages and directs all system activities during instruction execution?",["Arithmetic Logic Unit (ALU)","Control Unit (CU)","Registers","Cache"],"B",1,0,"381d8782c7a0"],["What distinguishes \"Firmware\" from standard application software?",["It is easily deleted by the user","It is permanently stored on hardware devices","It is used only for word processing","It requires a browser to execute tasks"],"B",1,0,"e2ca64c62219"],["In data communication, what is the role of the \"Protocol\"?",["To provide the physical path for the message","To act as a set of rules that governs data communications","To convert electrical signals into light","To increase the speed of the sender"],"B",1,0,"cb67e7d3c310"],["Which communication mode is compared to a \"two-way street\" where traffic flows in both directions at the same time?",["Simplex mode","Half-duplex mode","Full-duplex mode","Asynchronous mode"],"C",1,0,"b414f31fa08c"],["A network that spans an entire city, covering an area between \"5 to 50 km\", is officially a:",["LAN","WAN","MAN","VPN"],"C",1,0,"756b184c515d"],["Which category of application software includes tools like \"Microsoft Word\" and \"Google Sheets\"?",["Business Software","Productivity Software","Entertainment Software","Educational Software"],"B",1,0,"b98ca4b4c6f1"],["\"LMS\" (Learning Management Systems) are categorized as which type of software?",["Productivity","Business","Educational Software","System Utility"],"C",1,0,"1d43f53920a4"],["\"Mnemonics\" like MOV and ADD are the symbolic codes used in which language?",["Machine Language","Assembly Language","High Level Language","Java"],"B",1,0,"4abcc84f95f4"],["In a \"Star Topology\", what is the consequence if the central hub or switch fails?",["Only one computer stops working","The whole network goes down","Data starts traveling in a circle","The network automatically switches to Bus topology"],"B",1,0,"fe67ce7675b4"],["Which Internet technology allows data packets to potentially take \"different routes\" to reach their destination?",["Circuit Switching","Packet Switching","Simplex Transmission","Synchronous Timing"],"B",1,0,"7df53f62be55"],["What is listed as a significant \"Disadvantage\" of the Internet regarding human social behavior?",["Global Connectivity","Digital Addiction and social isolation","Real-time communication","Enhanced productivity"],"B",1,0,"628414348060"],["\"Walkie-talkies\" are the classic example of which communication mode?",["Simplex","Half-duplex","Full-duplex","Synchronous"],"B",1,0,"561289d8be77"],["Which transmission type uses \"Start and Stop bits\" because character timing is variable?",["Synchronous","Asynchronous","Parallel","Full-duplex"],"B",1,0,"11bf6e14cc0f"],["When you are \"reading a web page\" on your browser, which protocol is working behind the scenes?",["FTP","HTTP","SMTP","TCP"],"B",1,0,"ce3fcabcfa9e"],["FORTRAN and ALGOL are classic examples of which high-level language category?",["Procedural Languages","Structured Languages","Object-Oriented Languages","Machine Languages"],"A",1,0,"bf3521b9dd76"],["Data transmission from a computer to a printer, or broadcasting via radio and television, takes place in which mode?",["Simplex mode","Half-duplex mode","Full-duplex mode","Asynchronous mode"],"A",1,0,"9a06fde71277"],["Without which of the following component can two devices be physically connected but still unable to communicate or exchange information?",["Receiver","Medium","Protocol","Notice board"],"C",1,0,"3bedfe7f41f7"],["Which layer of the OSI model is explicitly responsible for converting data into a format that ensures compatibility across different systems?",["Application Layer","Presentation Layer","Session Layer","Transport Layer"],"B",1,0,"bde94699efca"],["Which OSI layer determines the optimal path for data transmission using devices like routers?",["Physical Layer","Data Link Layer","Network Layer","Application Layer"],"C",1,0,"7dbd018ad470"],["The modern global Internet originally evolved from a 1960s research project designed for military installations and research institutions. What was the name of this project?",["World Wide Web","Internet of Things","ARPANET","ISP Web"],"C",1,0,"4e5c563ff66c"],["A network setup that is typically smaller and usually consists of \"between two and ten computers\" is called:",["Client/Server Network","Peer-to-Peer Network","Dedicated Server Network","Central Switch Network"],"B",1,0,"267656649b92"],["Identify the system that exists independently of human design and invention.",["Solar system","Traffic system","School management system","Keyboard"],"A",1,0,"5b57fd7083b8"],["During the execute stage of the fetch-decode-execute cycle, which component actively transforms data using logic gates, while the others fetch, decode or hold data?",["Control Unit (CU)","Memory Unit (MU)","Arithmetic Logic Unit (ALU)","Register unit"],"C",3,0,"3a277ae8ac67"],["Which memory component temporarily stores active programs and data during execution but loses its contents when the power is turned off?",["Hard disk","ROM","RAM","USB flash drive"],"C",1,0,"d81e6fc4dc46"],["Whose invention provided the conceptual foundation for modern programmable computers?",["Alan Turing","Charles Babbage","Bill Gates","John von Neumann"],"B",3,0,"ac13c9469294"],["If a computer starts successfully but no application software can run, which of the following software is most likely still functioning?",["MS Word","Adobe Photoshop","Windows 11","Google Chrome"],"C",5,1,"e45a36380f41"],["A computer executes instructions accurately because one CPU component directs the activities of all other components. Which function does this component perform?",["Perform calculations","Store data permanently","Manage and coordinate all computer operations","Display graphics"],"C",3,1,"ccf771860ed4"],["Which type of memory is located closest to the CPU and stores frequently accessed data for faster processing?",["RAM","Cache memory","Hard disk","ROM"],"B",3,0,"41a65780573c"],["A system developed to solve a particular human need is classified as an artificial system because it:",["occurs naturally in the environment","is created by humans to achieve a specific goal","cannot be broken down into smaller parts","does not require any input"],"B",3,0,"560fce034e8a"],["Which of the following storage devices generally has the largest storage capacity in a typical modern PC?",["SSD (solid state drive)","CD-ROM","RAM","Cache memory"],"A",3,0,"5bc947eb3b87"],["A computer stores both program instructions and data in the same memory before execution. This feature is based on which concept?",["Stored-program concept","Graphical user interface","Mechanical computing","Cloud computing"],"A",3,1,"144c0e643b15"],["A user wants to organize numerical data, perform calculations and create charts. Which software is most suitable?",["Linux","macOS","MS Excel","BIOS"],"C",1,1,"32b367e8532a"],["If a computer stores information in the smallest possible binary form, which unit is being used?",["Byte","Kilobyte","Bit","Nibble"],"C",1,0,"8930c261be03"],["A team is assigned to develop an operating system instead of assembling computer hardware. Which area of work does this task belong to?",["Manufacturing processors","Designing circuits","Developing programs and operating systems","Building monitors"],"C",3,1,"42a7c9227eb6"],["A teacher wants to convert a printed worksheet into an editable digital document. Which device should be used?",["Monitor","Printer","Speaker","Scanner"],"D",1,1,"f1ee72d031d4"],["A computer loses the contents of its working memory when power is turned off, while another storage device keeps its data. This difference is mainly due to:",["Volatility of the memory","Colour and shape","Price and brand","The size of the device"],"A",3,1,"3d8f46bd4b6d"],["Which set of symbols is sufficient to represent all data and instructions in a digital computer?",["0 to 9","0 and 1","1 and 2","0 to 7"],"B",1,0,"5182d47e9b3a"],["A network gives each computer its own separate connection to a central device. Which is a direct advantage of this arrangement?",["Failure of one workstation does not affect the others","It needs no connecting device","It uses only a single communication cable","Every computer is directly connected to every other computer"],"A",5,1,"52c03f7eecf8"],["Which component interprets and executes program instructions while coordinating all processing in a computer?",["RAM","Motherboard","CPU","Hard disk"],"C",1,0,"80bf1e7151f5"],["A student scans old photos, types a report in MS Word and then prints it. How are the scanner, MS Word and the printer classified by function?",["Output, system software, input","Input, application software, output","Storage, utility software, input","Processing, hardware, software"],"B",5,1,"5a81bad03cc3"],["A pyramid shows CPU registers at the top (smallest, fastest, costliest), then cache, then RAM, and the hard disk at the bottom (largest, slowest, cheapest). This arrangement illustrates the:",["Memory hierarchy","Processing cycle","Network topology","Boot sequence"],"A",3,1,"0020d33c7880"],["A gamer's high-graphics game runs very slowly. He wants the CPU to reach game data much faster than reading it from the hard drive. Which component should he upgrade?",["Hard drive capacity","Monitor size","RAM size","Keyboard speed"],"C",5,1,"049052ab3694"],["A program calculates student grades. The Control Unit directs the flow and the result goes to the monitor. Which part actually calculates the average marks?",["Control Unit","Monitor","Arithmetic Logic Unit (ALU)","Hard disk"],"C",3,1,"f6aec489c11c"],["Fatima saves her data on a USB drive, unplugs it overnight, and finds all her data still there the next day. This shows the USB drive is a:",["Volatile storage device","Non-volatile storage device","Primary storage device","Temporary storage device"],"B",3,1,"74c87272560b"],["A teacher shows three pictures: a student typing on a keyboard, the CPU showing \"Processing\", and a printer producing a report. What do the three steps represent?",["Output, processing, input","Input, processing, output","Storage, input, output","Processing, storage, output"],"B",1,1,"2913251924f0"],["A new laptop (16 GB RAM, 512 GB SSD) costs five times more than an old one (4 GB RAM, 256 GB HDD). The price difference is MOSTLY due to the new laptop having:",["A larger screen","More RAM and a faster SSD","A different coloured case","More USB ports"],"B",3,1,"cdb5833a8a61"],["A hospital system takes heartbeat data, compares it with normal levels and alerts a nurse if the heart stops. This describes the basic functions of a computer system as:",["Artificial system","Data, information and processing","Natural system","Networking only"],"B",5,1,"83480b28e45d"],["During data communication, information travels through a fibre-optic cable from one device to another. The fibre-optic cable is the:",["Sender","Receiver","Transmission medium","Protocol"],"C",3,1,"d28f7ef219e6"],["A school has computer labs in two cities, each with its own local network, and the two networks are joined so teachers can share one database. The connection between the two is best described as a:",["PAN","LAN","WAN","VPN"],"C",5,1,"b7c40bd3e0fb"],["Student A says, \"Hardware is useless without software.\" Student B says, \"Software cannot run without hardware.\" Which conclusion is correct?",["Hardware is more important than software","Hardware and software are interdependent","Software is more important than hardware","They are independent of each other"],"B",3,1,"11e5648cbd9c"],["A student uses Wi-Fi to open a learning portal hosted in another country; the data passes through several interconnected networks. Which technology mainly enables this?",["LAN","Internet","Star topology","Ring topology"],"B",3,1,"e0dfc8967df2"],["A student records a voice note for an assignment. Which input device turns the student's voice into digital signals?",["Scanner","Microphone","Speaker","Webcam"],"B",1,1,"2112edea75a6"],["A cable company links its offices spread across one city, about 30 km apart. This network is a:",["LAN","MAN","WAN","PAN"],"B",3,1,"756b184c515d"],["Which register holds the address of the instruction to be fetched next?",["Accumulator","Program Counter","Instruction Register","Memory Data Register"],"B",3,0,"8819ee05fd3c"],["Short symbolic codes such as MOV, ADD and SUB are used in:",["machine language","assembly language","high-level languages only","HTML"],"B",1,0,"4abcc84f95f4"],["During a phone call both people can talk and listen at the same time. This uses which transmission mode?",["Simplex","Half-duplex","Full-duplex","Broadcast"],"C",3,1,"b414f31fa08c"],["Data that flows in only one direction, as from a keyboard to a computer, uses which mode?",["Simplex","Half-duplex","Full-duplex","Multiplex"],"A",3,0,"9a06fde71277"],["The part of the CPU that directs the flow of data and tells the other components what to do is the:",["ALU","Control Unit","Cache","Hard disk"],"B",3,0,"381d8782c7a0"],["Which protocol does a web browser use to request and load web pages?",["SMTP","FTP","HTTP","POP3"],"C",3,0,"ce3fcabcfa9e"],["The key idea of the Von Neumann architecture is that:",["instructions and data are stored together in the same memory","instructions are stored only on paper","data is kept only in registers","each program needs its own CPU"],"A",3,0,"9572ac25cbc0"],["The Internet grew out of a 1960s U.S. research network called:",["ARPANET","Ethernet","World Wide Web","Bluetooth"],"A",1,0,"4e5c563ff66c"],["A shopkeeper wants to turn a printed price list into a digital image on the computer. Which device should be used?",["Printer","Scanner","Plotter","Projector"],"B",1,1,"f1ee72d031d4"],["Which component is called the \"brain\" of the computer because it processes all instructions?",["RAM","Hard disk","CPU","Monitor"],"C",1,0,"80bf1e7151f5"],["A walkie-talkie lets only one person speak at a time, although both can speak. This is:",["simplex mode","half-duplex mode","full-duplex mode","broadcast mode"],"B",3,1,"b414f31fa08c"]]$j$::jsonb, true);
